    // Match the taskbar template: a full-size render surface, not a measured text/content slot.
    private Button CreatePreviewButton()
    {
        var ring = new FrameworkElementFactory(typeof(BatteryRing));
        ring.SetValue(FrameworkElement.HorizontalAlignmentProperty, HorizontalAlignment.Stretch);
        ring.SetValue(FrameworkElement.VerticalAlignmentProperty, VerticalAlignment.Stretch);
        var button = new Button
        {
            Template = new ControlTemplate(typeof(Button)) { VisualTree = ring },
            Background = Brushes.Transparent,
            BorderThickness = new Thickness(0), Padding = new Thickness(0),
            HorizontalContentAlignment = HorizontalAlignment.Stretch,
            VerticalContentAlignment = VerticalAlignment.Stretch,
            Focusable = false, IsTabStop = false
        };
        button.Loaded+=(_,_)=>SetPreviewContrast(button);return button;
    }
