    private void Slider(Panel p,string text,double v,double min,double max,double step,Action<double> set,bool play=false){
        var line=new Grid{Margin=new Thickness(0,4,0,4)};line.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(150)});line.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});line.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(72)});
