    private void ColorEditor(Panel p,string name,string value,Action<string> set){var exp=new Expander{Header=name+" · "+value,Margin=new Thickness(0,3,0,3)};var box=new StackPanel{Margin=new Thickness(10,4,0,5)};exp.Content=box;p.Children.Add(exp);var c=RingPreferences.Ink(value);var swatch=new Border{Height=20,Background=new SolidColorBrush(c),CornerRadius=new CornerRadius(4)};box.Children.Add(swatch);var field=new TextBox{Text=value,Margin=new Thickness(0,5,0,5)};box.Children.Add(field);var sliders=new Slider[4];bool syncing=false;void Apply(Color color){swatch.Background=new SolidColorBrush(color);string hex=color.A==255?$"#{color.R:X2}{color.G:X2}{color.B:X2}":color.ToString();exp.Header=name+" · "+hex;settingsModel.Apply(set,hex);}field.TextChanged+=(_,_)=>{if(syncing)return;try{var x=ParseColor(field.Text);syncing=true;for(int i=0;i<4;i++)sliders[i].Value=new[]{x.R,x.G,x.B,x.A}[i];syncing=false;Apply(x);}catch{syncing=false;}};for(int i=0;i<4;i++){var line=new DockPanel();var l=Label(new[]{"R","G","B","A"}[i]);l.Width=20;line.Children.Add(l);var num=new TextBox{Text=new[]{c.R,c.G,c.B,c.A}[i].ToString(),Width=48,Margin=new Thickness(5,0,0,3)};DockPanel.SetDock(num,Dock.Right);line.Children.Add(num);var sl=new Slider{Minimum=0,Maximum=255,Value=new[]{c.R,c.G,c.B,c.A}[i],TickFrequency=1,IsSnapToTickEnabled=true};sliders[i]=sl;line.Children.Add(sl);box.Children.Add(line);num.LostKeyboardFocus+=(_,_)=>{if(int.TryParse(num.Text,out int n))sl.Value=Math.Clamp(n,0,255);num.Text=((int)sl.Value).ToString();};num.KeyDown+=(_,e)=>{if(e.Key==System.Windows.Input.Key.Enter){if(int.TryParse(num.Text,out int n))sl.Value=Math.Clamp(n,0,255);num.Text=((int)sl.Value).ToString();}};sl.ValueChanged+=(_,_)=>{num.Text=((int)sl.Value).ToString();if(syncing||sliders.Any(s=>s==null))return;var x=Color.FromArgb((byte)sliders[3].Value,(byte)sliders[0].Value,(byte)sliders[1].Value,(byte)sliders[2].Value);syncing=true;field.Text=x.ToString();syncing=false;Apply(x);};}}
