    private void AppearancePreviewControls(){
        var row=new DockPanel();var val=Label((sample[0].Level??85)+"%");DockPanel.SetDock(val,Dock.Right);row.Children.Add(val);var lab=Label("模拟电量  ");DockPanel.SetDock(lab,Dock.Left);row.Children.Add(lab);var sl=new Slider{Minimum=0,Maximum=100,Value=sample[0].Level??85,TickFrequency=1,IsSnapToTickEnabled=true};row.Children.Add(sl);appearanceTest.Children.Add(row);
        sl.ValueChanged+=(_,_)=>{val.Text=((int)sl.Value)+"%";sample[0]=sample[0] with{Level=(int)sl.Value};UpdatePreview();};
        CheckPreview();void CheckPreview(){var cb=new CheckBox{Content="预览离线状态",IsChecked=sample[0].Offline};cb.Checked+=(_,_)=>{sample[0]=sample[0] with{Status="离线"};UpdatePreview();};cb.Unchecked+=(_,_)=>{sample[0]=sample[0] with{Status="已连接"};UpdatePreview();};appearanceTest.Children.Add(cb);var charge=new CheckBox{Content="预览充电状态",IsChecked=sample[0].Charging};charge.Checked+=(_,_)=>{cb.IsChecked=false;sample[0]=sample[0] with{Status="充电中",Charging=true};UpdatePreview();};charge.Unchecked+=(_,_)=>{sample[0]=sample[0] with{Charging=false,Status=sample[0].Offline?"离线":"已连接"};UpdatePreview();};cb.Checked+=(_,_)=>{charge.IsChecked=false;};appearanceTest.Children.Add(charge);}
    }
    private void PreviewDevice(TaskbarBattery d){if(nav.SelectedIndex!=1)return;var prior=sample[0];sample=Samples();sample[0]=d with{Level=prior.Level??85,Status=prior.Offline?"离线":prior.Charging?"充电中":"已连接",Charging=prior.Charging&&!prior.Offline,ShortLabel=null};UpdatePreview();}
    private StackPanel Group(Panel parent,string name){var p=new StackPanel{Margin=new Thickness(4,6,4,6)};parent.Children.Add(new Expander{Header=name,Content=p,IsExpanded=true,Margin=new Thickness(0,2,0,4)});return p;}
